OUT=pathlib.Path(__file__).resolve().parent;ROOT=OUT.parents[4];D=OUT.parent;Q=D/'qualified-editions4-cycle1-sourcefb';ORDERS=[61,62,64,69]
def read(p):return json.loads(p.read_text())
def sha(v):return hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def raw(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return str(p.relative_to(ROOT))
def save(n,d):(OUT/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
