def loc(match,detail):
 s=next(s for s in proof['rawSources'] if match in pathlib.Path(s['path']).name);return {'path':s['path'],'url':s['url'],'locator':detail}
ED=loc('dcrmr322','Полный сохранённый официальный DCRMR3.22 output L152–254 лично прочитан ранее и перечитан в FINAL:3.22.32.1 ручная печать обычно новое edition/issue;3.22.32.2 машинная/гравировальная печать скорее новый impression того же edition; примеры second impression/Third impression of first edition;3.22.33 default/alternative отдельного описания;3.22.35 number-line и3.22.36 многоязычные обозначения. Оговорки usually/more likely сохранены.')
REV=loc('dcrmr-named','Полный body DCRMR3.24 лично перечитан: определение/scope3.24.2/.21, обновление недостаточно для entirely new edition;3.24.3 corrected and improved и first American edition;3.24.32.1 обычное опускание substantially unchanged impression с возможным item note;3.24.32.2 отдельное описание + имеющееся designation edition → named revision, при отсутствии edition → designation edition; все First edition/fourth printing,1st-50th,fifth thousand,First Ace/third printing примеры;3.24.32.3 number line и3.24.33 языковые правила.')
G=loc('dcrmr-glossary','Полный body сохранённого DCRMR glossary лично прочитан в предшествующем INITIAL, идентичный rawSHA проверен: edition=same composition/master, impression=one printing event, issue=planned group, state/variant/item; facsimile exact copy обычно того же размера, часто photo/digital сейчас и engraving раньше; expression/work/manifestation и leaf/gathering. Старый SOURCE PASS не используется.')
IDP=loc('idp-dunhuang','Полностью перечитаны обе сохранённые релевантные статьи IDP L24–32 и118–126: электронная выставка неполна; китайский Zhong a han jing/Book of Middle-length Sayings, ink on paper, перевод Samghadeva; бумажному свитку предшествовали связанные и свёрнутые бамбуковые планки; paper sheets pasted/backed; отдельный Gem Heap Sutras сохранил исходный wooden roller и silk tie. Не заявляется чтение всего каталога.')
CRIT=loc('british-library-critical','Полная релевантная TEI-запись Or16490 лично перечитана: раннее13th/20th-century критическое издание Divan,11рукописей, многочисленные variants и marginal annotations, неизвестный editor,1919Iran colophon, красные разночтения/чёрные определения, codex on paper. Это конкретный рукописный пример, не универсальный11-count и не обязательное печатное издание.')
PAP=loc('british-library-papyrus','Полная запись BL Papyrus126 лично прочитана в предыдущем INITIAL, rawSHA идентичен:9листов сложены в18folios/36pages, видимые binding holes, первоначально правые страницы и позднее повторное использование левых. В текущих4 карточках не требуется как прямое основание; сохранён для сравнения носителей.')
BM=loc('british-museum-mesopotamia','В предыдущем INITIAL лично прочитаны полные релевантные страницы4–6 PDF из19, rawSHA идентичен: p5 влажная глина, reed/wood/ivory stylus, sun-hardening, восковые таблички и каменные надписи как альтернативы. Нового PDF/visual QA нет. В нынешних4 карточках прямого утверждения об этих носителях нет.')
main={61:('DCRMR3.22.32.2 даёт более вероятную трактовку impression/printing машинной эпохи как нового оттиска того же издания; исключён отдельный каталогизаторский вариант. Это не просто перевод слова «первое»: нужно отличить повторное печатание от нового edition/issue и особого field named revision. Один ключ и MEDIUM. Отдельно проверено близкое MAIN46:46 именует группу одного печатного события,61 проверяет условную трактовку уже данного обозначения в эпоху машинной печати.',[ED,REV,G]),62:('При всех данных условиях ключ фактически точен: отдельное описание substantially unchanged impression при имеющемся designation edition оформляют как designation of named revision. Но это точная специальная альтернатива3.24.32.2, а не обычное издательское знание; реальный HARD при frozen MEDIUM. Обычный знакомый с книгами читатель не выведет контринтуитивное поле named revision для неизменённого печатания. HOLD после единственного цикла.',[ED,REV]),64:('Сопоставление рукописных свидетелей и разночтений именует метод критического издания. Конкретная BL-запись демонстрирует11рукописей и аппарат вариантов; иные варианты описывают воспроизведение, хронологию или обновление. Один определяющий ключ, тематический MEDIUM. Первоначальная подмена edition на редакцию произведения в note2 устранена.',[CRIT,G,REV,ED]),69:('IDP подтверждает временную связь: связанные бамбуковые планки раньше бумажного свитка. Но варианты0/2 — утверждения о материальном тождестве, не временные последовательности; оба смешивают бамбук и готовые бумажные листы, так что только1/3 являются запрошенными последовательностями. Дополнительно MAIN совпадает/обращает ancient-world58: бамбуковые связки до бумаги. HOLD вариантов и MAIN, независимо от истинности ключа.',[IDP])}
expl={61:('Два предложения называют обычный повторный impression того же edition и сохраняют различие эпох/обычность.3.22.32.1/.2 подтверждают контраст; исключения не превращены в универсальное правило.',[ED]),62:('Два предложения фактически передают альтернативу с отдельным описанием и уже имеющимся обозначением издания. Условия сохранены. Однако смешение русского текста с необъяснёнными английскими названиями полей не снижает требуемое точное специальное знание до MEDIUM.',[REV,ED]),64:('Два предложения называют критическое издание и ограничивают11рукописей/варианты/заметки конкретным Divan-примером BL. Не утверждается, что каждое критическое издание имеет11свидетелей или должно быть печатным.',[CRIT]),69:('Два предложения верно передают направление bamboo→paper scroll и конструкцию бумажных листов. Истинность объяснения не исправляет некоординатные альтернативы и повтор MAIN древних носителей.',[IDP])}
notes={61:[('3.22.32.1 прямо даёт контраст ручного пресса: impression/printing обычно сигнализируют новое edition или issue. Это конкретное исключение относительно машинной эпохи вопроса, а не повтор ключа.',[ED]),('Для hand-press source обычно предполагает новое edition/issue; это истинная справка о предложенном результате, хотя условие вопроса machine-press другое.',[ED]),('В3.24.3.1 corrected and improved — точный пример designation of named revision рядом с Third edition. Положительный факт о собственном варианте, не отрицательная заглушка.',[REV]),('Glossary state различает копию/группу внутри того же impression/issue без отдельного публичного издательского усилия. Справка не объявляет всякое новое печатание новым state.',[G])],62:[('3.24.32.2 точно приводит First edition/fourth printing с отдельным описанием и note on edition statement о месте заимствования. Конкретный пример источника — добавка сверх абстрактной формы правила в prompt/key.',[REV]),('Обычный scope named revision: обновлено, но недостаточно для entirely new edition. Справка истинна об общем правиле; специфическая учётная альтернатива для unchanged impression прочитана отдельно и не отрицается.',[REV]),('3.24.32.1 обычную unchanged impression помету опускает без знака пропуска и позволяет Note on item при важности. Это истинный общий способ, не применимый вместо заданной alternative.',[REV]),('Основное правило действительно опускает impression statement без omission mark. Прямое указание, что это не данный separate-description alternative, относится к конкретному перепутанному правилу, не к пустому «не подходит».',[REV])],64:[('Glossary facsimile — exact copy, обычно тех же размеров. Выбор между текстовыми свидетелями — другая работа; это не утверждение, что факсимиле никогда не входит в критическое издание.',[G,CRIT]),('BL Or16490 называет Divan и11рукописей, numerous variant readings и marginal annotations. Это самостоятельные подробности конкретного критического издания сверх определения метода.',[CRIT]),('DCRMR3.22.32.2 для machine-press даёт more likely новый impression в том же edition. Нынешнее «обычно» сохраняет модальность; термин edition больше не подменён текстовой редакцией произведения.',[ED]),('3.24.21.1 описывает обновление названного edition, недостаточное для entirely new edition. Это общий scope; отдельная каталогизаторская alternative для unchanged impression не превращена в запрет.',[REV])],69:[('IDP различает inscribed bamboo slips tied/rolled и paper sheets pasted/backed into scroll. Справка верно называет конкретное смешение материалов в ложном составном варианте.',[IDP]),('IDP прямо называет bamboo slips earlier form, которую сменяет paper scroll. Справка исправляет обратную временную связь; повтор канонического верного факта в wrong-note допустим.',[IDP]),('IDP даёт склеенные бумажные листы для свитка и отдельно связанные бамбуковые планки. Справка конкретно исправляет ложное «обе формы бумажные».',[IDP]),('Первый пример IDP — китайский Book of Middle-length Sayings на бумаге; другой Gem Heap Sutras сохранил исходные валик и шёлковую завязку. Эти экземпляры не слиты в один и дают реальную добавку сверх chronology.',[IDP])]}
plaus={61:[('Повторный оттиск — правдоподобный результат рядом с изданием, редакцией и состоянием.','Ключ: machine-press wording обычно остаётся impression того же edition, с заданным исключением отдельной записи.'),('Новый edition/issue — реальная соседняя трактовка и обычная для hand-press эпохи.','Источник ограничивает эту обычность ручным прессом; вопрос задаёт машинную эпоху.'),('Named revision — реальная соседняя полевая трактовка, возможная в альтернативе отдельного описания.','Вопрос именно исключает отдельное описание, поэтому эту ветку применять нельзя.'),('State — реальный библиографический уровень отличий, легко спутать с impression.','State внутри оттиска/выпуска, а second impression обозначает другое печатание, не само по себе новый state.')],62:[('Это реальное поле каталожного описания, а не случайный термин.','Фактически единственный ключ при всех условиях3.24.32.2.'),('Designation edition — реальная соседняя ветка той же alternative.','Применяется при отсутствии обозначения издания; вопрос указывает, что оно уже есть.'),('Item note/опускание — реальный default той же главы.','Вопрос задаёт separate-description alternative, поэтому default не заменяет ключ.'),('Не записывать помету вообще — узнаваемое чтение правила об опускании.','В заданном separate-description случае помету записывают; к тому же форма ответа не параллельна названиям полей0/1 и гибридному2.')],64:[('Факсимиле также относится к старым оригиналам и рукописям, поэтому содержательный сосед.','Точное воспроизведение оригинала не именует метод сравнения свидетелей и аппарата разночтений.'),('Критическое издание — специализированный термин гуманитарной/книжной темы.','Его определяющий метод — сравнение свидетелей и фиксация разночтений.'),('Первое издание может впервые публиковать старый текст.','Оно задаёт хронологический признак, а не требуемый текстологический метод.'),('Переработанное издание действительно меняет/обновляет текст.','Обновление не тождественно специальной работе с рукописными свидетелями.')],69:[('FAIL: это не историческая последовательность, а смешение бамбуковых планок с бумажными листами.','Ложно по материалу и не отвечает на запрошенное временное отношение.'),('Реальная обратная последовательность тех же двух носителей — правдоподобная историческая альтернатива.','IDP утверждает обратное направление: бамбук раньше бумажного свитка.'),('FAIL: ещё одно материальное тождество, а не последовательность; противопоставленные носители объявлены бумажными.','Нет временного отношения, а бамбуковые планки не являются отдельными бумажными листами.'),('Верная историческая последовательность, но конкурирует фактически лишь с одним временным вариантом.','Фактический ключ подтверждён; это не исправляет вариантов0/2 и MAIN-повтора ancient58.') ]}
extras={61:('Для ручной печати impression/printing обычно сигнализируют новый edition/issue. Это контрастное условие отсутствует в machine-press prompt и дополняет ключ.',[ED]),62:('Конкретный пример First edition/fourth printing в руководстве; prompt даёт правило, но не этот дословный иллюстративный пример.',[REV]),64:('Именованный Divan-пример основан на11рукописях и имеет marginal annotations; конкретные экземплярные данные превышают общее определение критического метода.',[CRIT]),69:('Именованный китайский экземпляр Book of Middle-length Sayings и отдельный свиток с исходной шёлковой завязкой/валиком; это больше временного отношения bamboo→paper.',[IDP])}
levels={61:('medium','PASS','Различие printing/impression и edition с machine-press/hand-press условием знакомо регулярно соприкасающимся с книгоизданием/книжной библиографией; вне темы можно лишь сузить соседние термины. Прежний буквальный first→first cue удалён.'),62:('hard','FIX','Требуется точная специальная альтернативная процедура rare-material cataloging3.24.32.2: unchanged impression при отдельной записи и имеющемся edition записывают в поле named revision. Это не вывод из обычного знания обновлённого издания и не регулярное знание широкой книжно-издательской аудитории. По действующему guide точная экспертная деталь — HARD; frozen MEDIUM не достигнут.'),64:('medium','PASS','Термин критического издания по сравнению рукописей/вариантам требует текстологической или регулярной гуманитарной книжной привычки. Дистракторы — соседние типы изданий, а не чужие роли.'),69:('medium','FIX','Историческая последовательность конкретных китайских носителей содержательнее старого общего определения свитка и потенциально тематична. Но текущая задача не подтверждает полноценный MEDIUM:0/2 не являются последовательностями и смешивают материалы, оставляя только бинарное направление. Уровень не принимается отдельно от дефектного набора.')}
