 defects=[]
 if n==62:defects=[{'field':'difficulty/prompt-tested-knowledge','issue':levels[n][2],'owner':'Координатор01a14103; новый SOURCE/новое решение вне завершённого обычного cycle1.','nextNewSourceOrSolution':'Сохранить HOLD0. Нужен новый авторский маршрут с реальным MEDIUM-различием из книгоиздательской практики вместо точной специальной альтернативы rare-book cataloging; либо отдельное явное решение о смене frozen уровня. Сейчас не переименовывать HARD в MEDIUM и не запускать второй обычный цикл.','sourcesLocators':[REV,ED]},{'field':'orderedAnswers/parallel-language','issue':'Варианты смешивают названия полей и инструкции; explanation/notes используют необъяснённые английские названия DCRMR. Сам перевод или форматирование не исправят основной HARD/MEDIUM разрыв.','owner':'Координатор нового решения; не дополнительный обычный цикл этого пакета.','nextNewSourceOrSolution':'При новом решении дать параллельные читаемые русские варианты и оставить ровно необходимые термины, затем заново проверить аудиторию/один ключ.','sourcesLocators':[REV]}]
